function parseChoice(raw: string): Choice {
  const [text, result, mechanics = ""] = raw.split("~");
  const effects: Record<string, number> = {};
  let relationship: number | undefined;
  for (const token of mechanics.split(",").filter(Boolean)) {
    const [key, value] = token.split(":");
    if (key === "relationship") relationship = Number(value);
    else effects[key] = Number(value);
  }
  return {
    text,
    result,
    effects,
    ...(relationship === undefined ? {} : { relationship }),
  };
}

export const EVENTS: GameEvent[] = Object.entries(authored).flatMap(
  ([category, [minAge, maxAge, rows]], group) =>
    rows.map((row, index) => {
      const [title, description, ...choices] = row.split("|");
      return {
        id: `life-${group}-${index}`,
        category,
        minAge,
        maxAge,
        title,
        description,
        choices: choices.map(parseChoice),
      };
    }),
);

