for (const [name, category, startAge, rows] of chains) {
  rows.forEach((row, stage) => {
    const [title, description, ...rawChoices] = row.split("|");
    const choices = rawChoices.map((raw, index) => {
      const choice = parseChoice(raw);
      choice.flags =
        stage === 2
          ? { [`ending_${name}_${index}`]: 1, [`chain_${name}_complete`]: 1 }
          : index === 2
            ? { [`chain_${name}_abandoned`]: 1 }
            : {
                [`chain_${name}_${stage + 1}`]: 1,
                [`chain_${name}_path_${stage}_${index}`]: 1,
              };
      return choice;
    });
    EVENTS.push({
      id: `chain-${name}-${stage + 1}`,
      category,
      title,
      description,
      minAge: startAge + stage * 12,
      requires: stage ? { [`chain_${name}_${stage}`]: 1 } : undefined,
      choices,
    });
  });
}

